import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    cp = inputs["customer_profile"].copy()
    pc = inputs["profile_changes"].copy()

    # ---- build existing profile dict ----
    profile_dict = {}
    for _, row in cp.iterrows():
        cust_id = row["customer_id"]
        email = row["email"] if pd.notna(row["email"]) else None
        phone = row["phone"] if pd.notna(row["phone"]) else None
        tier = row["tier"] if pd.notna(row["tier"]) else None
        profile_dict[cust_id] = {
            "email": email,
            "phone": phone,
            "tier": tier,
            "updated_seq": row["updated_seq"],
        }

    # ---- group changes by customer, sorted by change_seq ----
    changes_by_cust = {}
    if len(pc) > 0:
        for cust_id, group in pc.groupby("customer_id"):
            changes_by_cust[cust_id] = group.sort_values("change_seq")

    all_cust_ids = set(profile_dict.keys()) | set(changes_by_cust.keys())

    def norm(v):
        # treat NaN / None as "null" marker meaning "unchanged"
        if v is None:
            return None
        try:
            if pd.isna(v):
                return None
        except (TypeError, ValueError):
            pass
        return v

    def apply_field_update(current, change_val, is_email=False):
        # change_val already normalized: None means "leave unchanged"
        if change_val is None:
            return current
        if isinstance(change_val, str) and change_val == "<<NULL>>":
            return None
        if is_email:
            return change_val.strip().lower()
        return change_val

    def values_equal(a, b):
        a_null = a is None
        b_null = b is None
        if a_null and b_null:
            return True
        if a_null != b_null:
            return False
        return a == b

    results = []

    for cust_id in all_cust_ids:
        state = profile_dict.get(cust_id)
        exists = state is not None

        if exists:
            cur_email = state["email"]
            cur_phone = state["phone"]
            cur_tier = state["tier"]
            cur_seq = state["updated_seq"]
        else:
            cur_email = cur_phone = cur_tier = None
            cur_seq = None

        changes = changes_by_cust.get(cust_id)
        if changes is not None:
            for _, ch in changes.iterrows():
                cseq = ch["change_seq"]

                if exists and cseq <= cur_seq:
                    continue

                ch_email = norm(ch["email"])
                ch_phone = norm(ch["phone"])
                ch_tier = norm(ch["tier"])

                if exists:
                    new_email = apply_field_update(cur_email, ch_email, is_email=True)
                    new_phone = apply_field_update(cur_phone, ch_phone)
                    new_tier = apply_field_update(cur_tier, ch_tier)

                    if (
                        values_equal(new_email, cur_email)
                        and values_equal(new_phone, cur_phone)
                        and values_equal(new_tier, cur_tier)
                    ):
                        # no-op change: do not advance watermark, do not alter state
                        continue
                    else:
                        cur_email, cur_phone, cur_tier = new_email, new_phone, new_tier
                        cur_seq = cseq
                else:
                    # create new customer row
                    cur_email = apply_field_update(None, ch_email, is_email=True)
                    cur_phone = apply_field_update(None, ch_phone)
                    cur_tier = apply_field_update(None, ch_tier)
                    cur_seq = cseq
                    exists = True

        if exists:
            results.append(
                {
                    "customer_id": cust_id,
                    "email": cur_email if cur_email is not None else np.nan,
                    "phone": cur_phone if cur_phone is not None else np.nan,
                    "tier": cur_tier if cur_tier is not None else np.nan,
                    "updated_seq": cur_seq,
                }
            )

    new_profile = pd.DataFrame(
        results, columns=["customer_id", "email", "phone", "tier", "updated_seq"]
    )

    if len(new_profile) > 0:
        new_profile["customer_id"] = new_profile["customer_id"].astype("int64")
        new_profile["updated_seq"] = new_profile["updated_seq"].astype("int64")
    else:
        new_profile = pd.DataFrame(
            {
                "customer_id": pd.Series(dtype="int64"),
                "email": pd.Series(dtype="object"),
                "phone": pd.Series(dtype="object"),
                "tier": pd.Series(dtype="object"),
                "updated_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_profile": new_profile}
